window.PHARMA_QUESTION_BANK = {"version":1,"sourceNote":"Banco construido exclusivamente desde las nueve guías elaboradas a partir del material entregado.","classes":[{"id":1,"title":"Introducción a la farmacología","short":"Introducción","focus":"Conceptos base, potencia, eficacia, seguridad e interacciones","accent":"#2B6EA6","questions":[{"id":"c1-q1","classId":1,"difficulty":"easy","prompt":"¿Qué estudia la farmacocinética?","options":["Los efectos del fármaco sobre el organismo","El recorrido ADME del fármaco","Solo los receptores","Solo las reacciones adversas"],"answer":1,"explanation":"La farmacocinética estudia lo que el organismo hace al fármaco mediante ADME. Los efectos del fármaco sobre el organismo corresponden a farmacodinamia."},{"id":"c1-q2","classId":1,"difficulty":"easy","prompt":"¿Qué concepto expresa el efecto máximo que puede alcanzar un fármaco?","options":["Potencia","Eficacia","Absorción","Tolerancia"],"answer":1,"explanation":"La eficacia indica el efecto máximo o Emax. La potencia señala cuánta dosis se necesita para lograr un efecto."},{"id":"c1-q3","classId":1,"difficulty":"easy","prompt":"¿Cuál es un medicamento y no solo el principio activo?","options":["Una sustancia activa aislada","Un producto con principio activo, excipientes y forma farmacéutica","Un receptor celular","Una enzima metabólica"],"answer":1,"explanation":"El medicamento es el producto terminado: principio activo, excipientes y forma farmacéutica. El principio activo aislado no basta para definirlo."},{"id":"c1-q4","classId":1,"difficulty":"easy","prompt":"¿Qué vía introduce el fármaco directamente en la sangre?","options":["Oral","Rectal","Intravenosa","Tópica"],"answer":2,"explanation":"La vía intravenosa deposita el fármaco directamente en la circulación. Por eso evita la etapa de absorción y tiene biodisponibilidad completa."},{"id":"c1-q5","classId":1,"difficulty":"easy","prompt":"¿Qué ejemplo se asocia a margen terapéutico estrecho?","options":["Digoxina","Metformina","Cafeína","Probenecid"],"answer":0,"explanation":"La digoxina es el ejemplo de la clase para margen terapéutico estrecho: la concentración eficaz está relativamente cerca de la tóxica."},{"id":"c1-q6","classId":1,"difficulty":"medium","prompt":"Dos fármacos logran el mismo efecto, pero A requiere menos dosis. ¿Qué se concluye?","options":["A es más eficaz","A es más potente","A tiene mayor toxicidad","A se elimina más rápido"],"answer":1,"explanation":"Si ambos alcanzan el mismo máximo, tienen eficacia comparable. El que necesita menor dosis es más potente."},{"id":"c1-q7","classId":1,"difficulty":"medium","prompt":"¿Por qué un antiácido puede reducir el efecto del levofloxacino?","options":["Aumenta su excreción","Impide su unión al receptor","Disminuye su absorción","Aumenta su eficacia"],"answer":2,"explanation":"Los antiácidos pueden disminuir la absorción de levofloxacino. Menor absorción implica menor exposición y posible pérdida de efecto."},{"id":"c1-q8","classId":1,"difficulty":"medium","prompt":"¿Qué secuencia explica el riesgo de eritromicina con ciclosporina?","options":["Mayor metabolismo, menor concentración, fracaso","Menor metabolismo, mayor concentración, toxicidad","Menor absorción, menor concentración, toxicidad","Mayor excreción, mayor concentración, toxicidad"],"answer":1,"explanation":"La eritromicina puede disminuir el metabolismo de ciclosporina. La concentración sube y aumenta el riesgo de toxicidad."},{"id":"c1-q9","classId":1,"difficulty":"medium","prompt":"¿Qué diferencia mejor un evento adverso de una reacción adversa?","options":["El evento siempre demuestra causalidad","La reacción aparece solo con sobredosis","El evento puede coincidir temporalmente sin demostrar causalidad","No existe diferencia"],"answer":2,"explanation":"Un evento adverso coincide temporalmente con el uso, pero no prueba causalidad. Una reacción adversa supone al menos una relación causal sospechada."},{"id":"c1-q10","classId":1,"difficulty":"medium","prompt":"¿Qué combinación representa un efecto sinérgico en el material?","options":["Paracetamol y tramadol","Paracetamol y cafeína","Amoxicilina y probenecid","Warfarina y hojas verdes"],"answer":1,"explanation":"El material presenta paracetamol con cafeína como sinergia. Paracetamol con tramadol aparece como ejemplo de efecto aditivo."},{"id":"c1-q11","classId":1,"difficulty":"hard","prompt":"Un paciente usa la misma dosis repetidamente y obtiene cada vez menos efecto. ¿Qué secuencia lo explica mejor?","options":["Mayor sensibilidad del receptor y mayor eficacia","Desensibilización y tolerancia","Mayor absorción y toxicidad","Incompatibilidad física"],"answer":1,"explanation":"La pérdida progresiva de respuesta con la misma dosis corresponde a tolerancia, que puede involucrar desensibilización de receptores."},{"id":"c1-q12","classId":1,"difficulty":"hard","prompt":"Un fármaco se elimina más lento por una interacción. ¿Qué cambio es más esperable?","options":["Menor concentración y menor duración","Mayor concentración y efecto más prolongado","Menor potencia sin cambio de concentración","Mayor eficacia máxima obligatoria"],"answer":1,"explanation":"Si la eliminación disminuye, el fármaco se acumula. Esto eleva su concentración y puede prolongar tanto el efecto como la toxicidad."},{"id":"c1-q13","classId":1,"difficulty":"hard","prompt":"Una mezcla intravenosa forma un precipitado antes de administrarse. ¿Cómo se clasifica?","options":["Evento adverso","Tolerancia","Incompatibilidad","Sinergia"],"answer":2,"explanation":"La formación de precipitado antes de administrar es una incompatibilidad física. No debe confundirse con una reacción adversa del paciente."},{"id":"c1-q14","classId":1,"difficulty":"hard","prompt":"Un fármaco produce el mismo máximo que otro, pero con una dosis menor. ¿Cuál es la interpretación correcta?","options":["Es más potente, pero no necesariamente más eficaz","Es más eficaz, pero no más potente","Tiene mayor margen terapéutico","Tiene menor absorción"],"answer":0,"explanation":"Alcanzar el mismo Emax indica eficacia similar. Requerir menor dosis indica mayor potencia, no necesariamente mayor seguridad."},{"id":"c1-q15","classId":1,"difficulty":"hard","prompt":"Una interacción eleva la concentración de un fármaco con margen estrecho. ¿Por qué es especialmente riesgosa?","options":["Porque el efecto terapéutico desaparece siempre","Porque la dosis tóxica está cerca de la eficaz","Porque impide toda distribución","Porque transforma el fármaco en placebo"],"answer":1,"explanation":"En un margen estrecho, un aumento pequeño de concentración puede acercar el fármaco al rango tóxico. Por eso las interacciones son especialmente relevantes."}]},{"id":2,"title":"Farmacología antiinfecciosa","short":"Antiinfecciosa","focus":"Toxicidad selectiva, mecanismos, PK/PD y resistencia","accent":"#26715B","questions":[{"id":"c2-q1","classId":2,"difficulty":"easy","prompt":"¿Qué describe mejor la toxicidad selectiva?","options":["Dañar por igual al huésped y al patógeno","Atacar una diferencia del microorganismo","Usar siempre amplio espectro","Evitar toda reacción adversa"],"answer":1,"explanation":"La toxicidad selectiva busca una diferencia del microorganismo que permita dañarlo más que al huésped."},{"id":"c2-q2","classId":2,"difficulty":"easy","prompt":"¿Qué hace un bacteriostático?","options":["Rompe siempre la membrana","Detiene la multiplicación bacteriana","Destruye virus","Aumenta la inmunidad directamente"],"answer":1,"explanation":"Un bacteriostático frena la multiplicación. La eliminación final depende en mayor medida de las defensas del paciente."},{"id":"c2-q3","classId":2,"difficulty":"easy","prompt":"¿Qué grupo inhibe la pared celular al unirse a PBP?","options":["Macrólidos","Beta-lactámicos","Quinolonas","Aminoglucósidos"],"answer":1,"explanation":"Los beta-lactámicos se unen a PBP e impiden construir correctamente la pared bacteriana."},{"id":"c2-q4","classId":2,"difficulty":"easy","prompt":"¿Qué patrón PK/PD caracteriza a los beta-lactámicos?","options":["Tiempo sobre CMI","Solo vida media","Solo unión a proteínas","Concentración máxima aislada"],"answer":0,"explanation":"La eficacia de los beta-lactámicos depende del tiempo durante el cual su concentración permanece sobre la CMI."},{"id":"c2-q5","classId":2,"difficulty":"easy","prompt":"Cuando se identifica el patógeno, ¿qué principio debe guiar la elección?","options":["Mantener siempre dos antibióticos","Usar el espectro más estrecho eficaz","Cambiar siempre a Reserve","Suspender sin evaluar"],"answer":1,"explanation":"Con el patógeno identificado se debe desescalar al espectro más estrecho que siga siendo eficaz."},{"id":"c2-q6","classId":2,"difficulty":"medium","prompt":"¿Qué combinación mecanismo-riesgo corresponde a aminoglucósidos?","options":["50S y hepatotoxicidad","30S y nefro/ototoxicidad","PBP y disbiosis","Ergosterol y resistencia viral"],"answer":1,"explanation":"Los aminoglucósidos alteran la subunidad 30S y se asocian de forma característica con nefrotoxicidad y ototoxicidad."},{"id":"c2-q7","classId":2,"difficulty":"medium","prompt":"¿Cuál es el blanco de ciprofloxacino y levofloxacino?","options":["PBP","ADN girasa y topoisomerasa IV","Ergosterol","Peptidiltransferasa exclusivamente"],"answer":1,"explanation":"Ciprofloxacino y levofloxacino inhiben ADN girasa y topoisomerasa IV, necesarias para la replicación bacteriana."},{"id":"c2-q8","classId":2,"difficulty":"medium","prompt":"¿Por qué el uso innecesario favorece resistencia?","options":["Elimina toda variación genética","Selecciona microorganismos capaces de sobrevivir","Impide la transferencia genética","Aumenta siempre la inmunidad"],"answer":1,"explanation":"El antibiótico elimina microorganismos sensibles y deja ventaja a los que sobreviven. Esa presión selecciona resistencia."},{"id":"c2-q9","classId":2,"difficulty":"medium","prompt":"Tras recibir un antibiograma sensible a un fármaco estrecho, ¿qué conducta expresa desescalamiento?","options":["Agregar colistina","Mantener cobertura máxima","Cambiar al agente estrecho eficaz","Suspender toda vigilancia"],"answer":2,"explanation":"Cambiar desde cobertura amplia a un agente estrecho sustentado por el antibiograma es desescalamiento."},{"id":"c2-q10","classId":2,"difficulty":"medium","prompt":"¿En qué categoría AWaRe se ubica colistina?","options":["Access","Watch","Reserve","Profilaxis"],"answer":2,"explanation":"Colistina se ubica en Reserve: debe preservarse para situaciones seleccionadas con pocas alternativas."},{"id":"c2-q11","classId":2,"difficulty":"hard","prompt":"Paciente inmunosuprimido con infección grave recibe un bacteriostático. ¿Qué preocupación explica mejor el material?","options":["El fármaco depende más de que el sistema inmune elimine bacterias","El fármaco siempre produce lisis inmediata","El espectro estrecho impide toda eficacia","La CMI deja de existir"],"answer":0,"explanation":"Al frenar el crecimiento sin producir lisis inmediata, un bacteriostático depende más de la respuesta inmune, algo relevante en inmunosupresión grave."},{"id":"c2-q12","classId":2,"difficulty":"hard","prompt":"En sospecha de sepsis grave, ¿cuál es la secuencia más adecuada?","options":["Esperar el antibiograma antes de actuar","Tomar cultivos si es posible e iniciar terapia sin retraso injustificado","Usar solo Reserve","Omitir cultivos y mantener tratamiento indefinido"],"answer":1,"explanation":"En sepsis se obtienen cultivos si no retrasan la terapia, pero el antibiótico urgente no debe esperar injustificadamente el resultado."},{"id":"c2-q13","classId":2,"difficulty":"hard","prompt":"Un paciente crítico presenta edema y tercer espacio. ¿Qué grupo puede cambiar especialmente su distribución por ser hidrofílico?","options":["Macrólidos","Beta-lactámicos","Clindamicina","Rifampicina"],"answer":1,"explanation":"Los beta-lactámicos son hidrofílicos. El edema y el tercer espacio pueden aumentar su volumen de distribución y alterar la exposición."},{"id":"c2-q14","classId":2,"difficulty":"hard","prompt":"Se retrasa repetidamente un beta-lactámico. ¿Cuál es la consecuencia farmacológica más directa?","options":["Mayor tiempo sobre CMI","Caída bajo la CMI y menor eficacia","Mayor efecto postantibiótico","Conversión en bacteriostático"],"answer":1,"explanation":"Los retrasos permiten que la concentración caiga bajo la CMI. En un fármaco tiempo-dependiente eso reduce la oportunidad de acción."},{"id":"c2-q15","classId":2,"difficulty":"hard","prompt":"Una bacteria produce carbapenemasa y además expulsa el fármaco. ¿Qué mecanismos combina?","options":["Inactivación enzimática y eflujo","Mutación y absorción intestinal","Sinergia y distribución","Translocación y lisis osmótica"],"answer":0,"explanation":"La carbapenemasa inactiva el antibiótico; la bomba de eflujo lo expulsa. Son dos mecanismos de resistencia distintos que pueden coexistir."}]},{"id":3,"title":"Desarrollo de fármacos y fases clínicas","short":"Desarrollo","focus":"Preclínica, fases I-IV, ética y formulación","accent":"#B87413","questions":[{"id":"c3-q1","classId":3,"difficulty":"easy","prompt":"¿Cuál es el objetivo general del desarrollo de fármacos?","options":["Aumentar el número de excipientes","Encontrar terapias seguras y eficaces","Evitar toda evaluación animal","Comercializar antes de estudiar seguridad"],"answer":1,"explanation":"El desarrollo busca demostrar que una terapia ofrece eficacia con una seguridad aceptable antes y después de su aprobación."},{"id":"c3-q2","classId":3,"difficulty":"easy","prompt":"¿Qué caracteriza un estudio in vitro?","options":["Se realiza en seres humanos","Se realiza fuera de un organismo en condiciones controladas","Solo evalúa costos","Corresponde siempre a Fase IV"],"answer":1,"explanation":"In vitro significa fuera de un organismo vivo, bajo condiciones controladas de laboratorio."},{"id":"c3-q3","classId":3,"difficulty":"easy","prompt":"¿Qué pertenece a la evaluación preclínica in vivo?","options":["Pruebas en organismos vivos antes de humanos","Venta del medicamento","Farmacovigilancia poscomercialización","Consentimiento de consumidores"],"answer":0,"explanation":"La evaluación preclínica in vivo usa organismos vivos antes de la exposición inicial en seres humanos."},{"id":"c3-q4","classId":3,"difficulty":"easy","prompt":"¿Cuál es la prioridad de Fase I?","options":["Confirmar eficacia poblacional","Seguridad, tolerabilidad y dosis","Detectar eventos extremadamente raros","Comparar costos de mercado"],"answer":1,"explanation":"Fase I prioriza seguridad, tolerabilidad, farmacocinética y rango de dosis en grupos pequeños."},{"id":"c3-q5","classId":3,"difficulty":"easy","prompt":"¿Cuándo ocurre Fase IV?","options":["Antes del descubrimiento","Después de la aprobación","Solo in vitro","Antes de toda evaluación toxicológica"],"answer":1,"explanation":"Fase IV ocurre después de la aprobación y permite observar el medicamento en uso amplio y prolongado."},{"id":"c3-q6","classId":3,"difficulty":"medium","prompt":"¿Qué diferencia central tiene Fase II respecto de Fase I?","options":["Incluye pacientes y busca eficacia preliminar y dosis terapéutica","Ocurre después de comercializar","No evalúa seguridad","Se limita a estudios in vitro"],"answer":0,"explanation":"Fase II incorpora pacientes con la enfermedad para explorar eficacia y escoger una dosis terapéutica."},{"id":"c3-q7","classId":3,"difficulty":"medium","prompt":"¿Qué objetivo distingue a Fase III?","options":["Explorar microdosis","Confirmar eficacia en una población mayor frente a un comparador","Estudiar solo voluntarios sanos","Diseñar excipientes"],"answer":1,"explanation":"Fase III confirma eficacia y seguridad en poblaciones mayores, habitualmente frente a placebo o tratamiento comparador."},{"id":"c3-q8","classId":3,"difficulty":"medium","prompt":"¿Qué debe garantizar el consentimiento informado?","options":["Participación obligatoria","Decisión libre basada en información comprensible","Ausencia total de riesgo","Beneficio terapéutico asegurado"],"answer":1,"explanation":"El consentimiento exige información comprensible y una decisión libre. No promete ausencia de riesgo ni beneficio asegurado."},{"id":"c3-q9","classId":3,"difficulty":"medium","prompt":"¿Qué describe mejor el diseño racional?","options":["Elegir una molécula al azar","Diseñar según mecanismo y estructura del blanco","Omitir pruebas preclínicas","Usar solo productos naturales"],"answer":1,"explanation":"El diseño racional parte del mecanismo y de la estructura del blanco para proponer una molécula con interacción útil."},{"id":"c3-q10","classId":3,"difficulty":"medium","prompt":"¿Qué factores del material orientan la formulación?","options":["Solo el precio","Barreras, vía, urgencia y estabilidad","Solo el color del envase","Únicamente la edad del investigador"],"answer":1,"explanation":"La formulación debe responder a barreras biológicas, vía disponible, rapidez necesaria y estabilidad del producto."},{"id":"c3-q11","classId":3,"difficulty":"hard","prompt":"Un candidato se administra por primera vez a un pequeño grupo sano con escalamiento de dosis. ¿Qué fase es?","options":["Fase 0","Fase I","Fase II","Fase IV"],"answer":1,"explanation":"La primera administración con escalamiento de dosis en un grupo pequeño corresponde a Fase I, no a Fase 0."},{"id":"c3-q12","classId":3,"difficulty":"hard","prompt":"Pacientes con la enfermedad se asignan al candidato o control para estimar eficacia y seleccionar dosis. ¿Qué fase corresponde?","options":["Preclínica","Fase I","Fase II","Fase IV"],"answer":2,"explanation":"Pacientes asignados a candidato o control para estimar eficacia y seleccionar dosis corresponden a Fase II."},{"id":"c3-q13","classId":3,"difficulty":"hard","prompt":"Un estudio multicéntrico compara el candidato con terapia estándar para confirmar eficacia y reacciones comunes. ¿Qué fase es?","options":["Fase 0","Fase I","Fase III","Fase IV"],"answer":2,"explanation":"Un ensayo multicéntrico grande que confirma eficacia frente al estándar corresponde a Fase III."},{"id":"c3-q14","classId":3,"difficulty":"hard","prompt":"Tras la comercialización aparece una reacción rara no observada antes. ¿Qué explica mejor su detección?","options":["Fase IV expone a más personas durante más tiempo","Fase I elimina todo riesgo","Los excipientes impiden eventos raros","In vitro reproduce toda la población"],"answer":0,"explanation":"Los eventos raros pueden emerger en Fase IV porque aumenta mucho el número de personas y el tiempo de exposición."},{"id":"c3-q15","classId":3,"difficulty":"hard","prompt":"El mismo principio activo se formula como presentación de liberación más rápida por una urgencia clínica. ¿Qué concepto explica la decisión?","options":["Transferencia genética","Tecnología farmacéutica","Placebo","Diseño de Fase IV"],"answer":1,"explanation":"La tecnología farmacéutica adapta la forma de dosificación y la liberación a la necesidad clínica, aun con el mismo principio activo."}]},{"id":4,"title":"Prescripción y Ley de Fármacos en Chile","short":"Prescripción","focus":"Recetas, trazabilidad, bioequivalencia y rol de enfermería","accent":"#A84A43","questions":[{"id":"c4-q1","classId":4,"difficulty":"easy","prompt":"¿Qué es la prescripción?","options":["Solo una recomendación verbal","Un acto profesional y legal que indica tratamiento","La entrega del medicamento","El registro de enfermería"],"answer":1,"explanation":"La prescripción es un acto profesional y legal que comunica un tratamiento concreto; no es solo una sugerencia verbal."},{"id":"c4-q2","classId":4,"difficulty":"easy","prompt":"¿Qué dato pertenece a las indicaciones de uso?","options":["Dosis y frecuencia","Marca del timbre","Precio de la farmacia","Número de sala"],"answer":0,"explanation":"Dosis y frecuencia indican cuánto administrar y cada cuánto tiempo, por lo que son datos esenciales de uso."},{"id":"c4-q3","classId":4,"difficulty":"easy","prompt":"¿Qué receta se usa para la mayoría de medicamentos sin control especial?","options":["Simple","Cheque","Retenida","Veterinaria obligatoria"],"answer":0,"explanation":"Según la clase, la receta simple se utiliza para la mayoría de los medicamentos que no requieren control especial."},{"id":"c4-q4","classId":4,"difficulty":"easy","prompt":"¿Qué identifica de forma única una receta electrónica?","options":["El color","El folio","La marca del fármaco","La edad del farmacéutico"],"answer":1,"explanation":"El folio individualiza la receta electrónica y permite seguir su emisión y dispensación."},{"id":"c4-q5","classId":4,"difficulty":"easy","prompt":"Según el material, ¿prescribe medicamentos el personal de enfermería?","options":["Sí, todos","No; verifica y administra según indicación","Solo psicotrópicos","Solo estupefacientes"],"answer":1,"explanation":"El material distingue el rol de enfermería: verificar la indicación, administrar con seguridad y registrar, no prescribir medicamentos."},{"id":"c4-q6","classId":4,"difficulty":"medium","prompt":"¿Qué conjunto corresponde a una prescripción racional?","options":["Diagnóstico, selección, dosis, duración y comunicación","Solo marca y precio","Solo diagnóstico","Folio y timbre sin indicaciones"],"answer":0,"explanation":"Una prescripción racional integra diagnóstico, elección del fármaco, dosis, duración y comunicación comprensible."},{"id":"c4-q7","classId":4,"difficulty":"medium","prompt":"¿Qué característica distingue a la receta cheque?","options":["No tiene control especial","Es oficial, seriada y se usa para estupefacientes","Nunca se retiene","Tiene vigencia indefinida"],"answer":1,"explanation":"La receta cheque es oficial y seriada, y se asocia en la clase al control de estupefacientes."},{"id":"c4-q8","classId":4,"difficulty":"medium","prompt":"¿Qué busca la prescripción por principio activo?","options":["Impedir comparar alternativas","Permitir reconocer alternativas y costos","Eliminar la concentración","Sustituir la dosis por una marca"],"answer":1,"explanation":"El principio activo permite reconocer alternativas equivalentes o bioequivalentes y comparar costos sin depender solo de una marca."},{"id":"c4-q9","classId":4,"difficulty":"medium","prompt":"¿Por qué el SNRE reduce reutilización fraudulenta?","options":["Borra el nombre del paciente","Marca la receta como dispensada","Elimina la verificación farmacéutica","No utiliza folio"],"answer":1,"explanation":"Al marcar la receta como dispensada, el sistema conserva trazabilidad y dificulta que vuelva a utilizarse."},{"id":"c4-q10","classId":4,"difficulty":"medium","prompt":"¿Qué acción de enfermería mantiene la trazabilidad?","options":["Omitir la hora","Registrar fármaco, dosis, hora y vía","Cambiar la receta","Prescribir una alternativa"],"answer":1,"explanation":"Registrar fármaco, dosis, hora y vía deja evidencia de lo administrado y permite reconstruir el proceso."},{"id":"c4-q11","classId":4,"difficulty":"hard","prompt":"Una receta indica clonazepam y la farmacia debe conservarla. ¿Qué tipo reconoce el material?","options":["Simple","Cheque","Retenida","Sin receta"],"answer":2,"explanation":"El clonazepam aparece en el material como ejemplo de medicamento sujeto a receta retenida."},{"id":"c4-q12","classId":4,"difficulty":"hard","prompt":"Una indicación tiene nombre del fármaco, pero no concentración, dosis ni frecuencia. ¿Cuál es el problema principal?","options":["Falta información esencial para dispensar y usar con seguridad","No tiene marca comercial","No usa receta electrónica","No informa el precio"],"answer":0,"explanation":"Sin concentración, dosis ni frecuencia no puede dispensarse ni administrarse de manera inequívoca y segura."},{"id":"c4-q13","classId":4,"difficulty":"hard","prompt":"La enfermera detecta una dosis muy superior a la habitual antes de administrar. ¿Qué conducta refleja su rol?","options":["Administrar y registrar después","Detener, verificar y notificar","Modificar la receta por cuenta propia","Desechar toda la ficha"],"answer":1,"explanation":"Ante una dosis inusual, enfermería debe detener el proceso, verificar la indicación y notificar. No corresponde modificarla por cuenta propia."},{"id":"c4-q14","classId":4,"difficulty":"hard","prompt":"Un paciente pregunta por una alternativa bioequivalente más económica. ¿Qué punto de la Ley 20.724 se aplica?","options":["Prohibición de informar alternativas","Información al paciente y prescripción por principio activo","Uso obligatorio de receta cheque","Tráfico ilícito"],"answer":1,"explanation":"La Ley 20.724 se relaciona en la clase con información al paciente y prescripción por principio activo para facilitar alternativas."},{"id":"c4-q15","classId":4,"difficulty":"hard","prompt":"Una receta electrónica ya figura como dispensada. ¿Por qué no debe utilizarse de nuevo?","options":["Porque el cierre asegura trazabilidad y evita duplicación","Porque desaparece el principio activo","Porque cambia a receta simple","Porque enfermería prescribe otra"],"answer":0,"explanation":"El cierre electrónico evita duplicación y mantiene la trazabilidad de una receta que ya fue dispensada."}]},{"id":5,"title":"RAM y farmacovigilancia","short":"Farmacovigilancia","focus":"Tipos de RAM, causalidad, ESAVI y notificación","accent":"#247C83","questions":[{"id":"c5-q1","classId":5,"difficulty":"easy","prompt":"¿Cuál es el objetivo central de la farmacovigilancia?","options":["Promover y vigilar el uso seguro de medicamentos","Reemplazar los ensayos clínicos","Autorizar recetas","Aumentar las dosis"],"answer":0,"explanation":"La farmacovigilancia busca detectar, evaluar, comprender y prevenir problemas asociados a medicamentos para promover un uso seguro."},{"id":"c5-q2","classId":5,"difficulty":"easy","prompt":"¿Cuál situación cumple la definición de RAM presentada?","options":["Daño no buscado con dosis habitual","Intoxicación por dosis excesiva","Síntoma previo al medicamento","Error sin manifestación clínica"],"answer":0,"explanation":"La definición presentada de RAM exige un daño no buscado que aparece con dosis usadas habitualmente. La sobredosis se analiza de otra manera."},{"id":"c5-q3","classId":5,"difficulty":"easy","prompt":"¿Qué caracteriza a una RAM tipo A?","options":["Es dependiente de dosis y predecible","Siempre es alérgica","Es independiente de dosis","Solo aparece años después"],"answer":0,"explanation":"Las RAM tipo A son aumentadas: se relacionan con el efecto farmacológico, suelen depender de dosis y son más predecibles."},{"id":"c5-q4","classId":5,"difficulty":"easy","prompt":"¿Qué significa ESAVI?","options":["Evento posterior a inmunización que debe investigarse","Reacción causada con certeza por una vacuna","Error exclusivo del fabricante","RAM producida solo por sobredosis"],"answer":0,"explanation":"ESAVI describe un evento posterior a una inmunización que debe investigarse. La temporalidad por sí sola no demuestra causalidad."},{"id":"c5-q5","classId":5,"difficulty":"easy","prompt":"¿Cuál es la vía oficial de reporte indicada para Chile?","options":["SVI","Receta cheque","Ficha en papel únicamente","Uppsala directamente"],"answer":0,"explanation":"El material identifica al SVI como la vía oficial de reporte en Chile."},{"id":"c5-q6","classId":5,"difficulty":"medium","prompt":"¿Por qué una RAM tipo A suele poder prevenirse?","options":["Porque se relaciona con el efecto farmacológico y la dosis","Porque nunca depende de la exposición","Porque siempre es coincidente","Porque solo aparece con vacunas"],"answer":0,"explanation":"Como la tipo A se relaciona con mecanismo y exposición, ajustar dosis o detectar interacciones puede prevenir parte de estos casos."},{"id":"c5-q7","classId":5,"difficulty":"medium","prompt":"Una RAM ocurre en 1 de cada 500 pacientes. ¿Cómo se clasifica por frecuencia?","options":["Infrecuente","Muy frecuente","Rara","Muy rara"],"answer":0,"explanation":"Una frecuencia de 1 en 500 corresponde a 0,2%, clasificada como infrecuente en la escala enseñada."},{"id":"c5-q8","classId":5,"difficulty":"medium","prompt":"¿Qué plazo corresponde a una RAM seria conocida por un profesional de salud?","options":["72 horas","15 días","30 días","6 meses"],"answer":0,"explanation":"La clase establece 72 horas para reportar una RAM seria conocida por un profesional de salud."},{"id":"c5-q9","classId":5,"difficulty":"medium","prompt":"¿Qué dato fortalece la causalidad en el algoritmo de Naranjo?","options":["La reacción mejora al retirar el fármaco","Existen causas alternativas claras","El evento precedió al fármaco","No existe evidencia objetiva"],"answer":0,"explanation":"La mejoría tras retirar el fármaco es un dechallenge positivo y aumenta la plausibilidad de una relación causal."},{"id":"c5-q10","classId":5,"difficulty":"medium","prompt":"¿Cuál ESAVI se considera prevenible en la clasificación presentada?","options":["Relacionado con error de inmunización","Relacionado con ansiedad","Evento coincidente","Relacionado con propiedad inherente"],"answer":0,"explanation":"Los eventos por errores de preparación, almacenamiento o administración se consideran prevenibles."},{"id":"c5-q11","classId":5,"difficulty":"hard","prompt":"Un paciente desarrolla bradicardia tras aumentar la dosis de un bloqueador beta y mejora al reducirla. ¿Qué interpretación integra mejor el caso?","options":["RAM tipo A con relación dosis-respuesta","RAM tipo B independiente de dosis","ESAVI coincidente","Intoxicación necesariamente voluntaria"],"answer":0,"explanation":"La bradicardia tras aumentar un beta bloqueador es predecible por su mecanismo y muestra relación dosis-respuesta: patrón tipo A."},{"id":"c5-q12","classId":5,"difficulty":"hard","prompt":"Tras una vacuna aparece síncope provocado por ansiedad al procedimiento. ¿Cómo se clasifica el ESAVI?","options":["Relacionado con ansiedad por inmunización","Defecto de calidad","Propiedad inherente de la vacuna","Evento causado por sobredosis"],"answer":0,"explanation":"El síncope provocado por temor o procedimiento se clasifica como ESAVI relacionado con ansiedad por inmunización."},{"id":"c5-q13","classId":5,"difficulty":"hard","prompt":"Un paciente usa analgésicos durante años y desarrolla necrosis papilar. ¿Qué tipo de RAM sugiere el material?","options":["Tipo C","Tipo A","Tipo B","ESAVI tipo E"],"answer":0,"explanation":"La RAM tipo C aparece con exposición crónica; la necrosis papilar por uso prolongado es el ejemplo del material."},{"id":"c5-q14","classId":5,"difficulty":"hard","prompt":"Una reacción aparece después del medicamento, mejora al retirarlo, reaparece al reintroducirlo y no tiene otra causa clara. ¿Qué ocurre con la imputabilidad?","options":["Aumenta la probabilidad causal","Disminuye automáticamente a dudosa","Solo demuestra frecuencia","Deja de ser notificable"],"answer":0,"explanation":"Mejoría al retirar, reaparición al reintroducir y ausencia de causas alternativas fortalecen notablemente la imputabilidad."},{"id":"c5-q15","classId":5,"difficulty":"hard","prompt":"Un profesional duda si un rash es enfermedad o RAM y decide no reportarlo. ¿Qué problema genera esta conducta?","options":["Infranotificación y pérdida de señales","Mayor trazabilidad","Confirmación de causalidad","Aumento de biodisponibilidad"],"answer":0,"explanation":"No reportar sospechas produce infranotificación y dificulta detectar señales. No se necesita certeza absoluta para notificar."}]},{"id":6,"title":"Farmacología en poblaciones especiales","short":"Poblaciones","focus":"Adulto mayor, embarazo, lactancia y pediatría","accent":"#775C9B","questions":[{"id":"c6-q1","classId":6,"difficulty":"easy","prompt":"¿Qué principio orienta el tratamiento en poblaciones especiales?","options":["Valorar beneficio/riesgo y elegir la opción más segura","Usar siempre la dosis adulta","Evitar toda farmacoterapia","Preferir polifarmacia"],"answer":0,"explanation":"En poblaciones especiales se individualiza el tratamiento equilibrando beneficio y riesgo y escogiendo la opción más segura que conserve eficacia."},{"id":"c6-q2","classId":6,"difficulty":"easy","prompt":"¿Qué suele ocurrir con el aclaramiento renal en el adulto mayor?","options":["Disminuye","Aumenta siempre","No cambia","Se vuelve independiente de la edad"],"answer":0,"explanation":"El aclaramiento renal suele disminuir con la edad, aunque la creatinina aislada no siempre refleje bien ese cambio."},{"id":"c6-q3","classId":6,"difficulty":"easy","prompt":"¿Cuál es el período de máxima susceptibilidad a malformaciones?","options":["Organogénesis hasta aproximadamente la semana 8","Solo durante el parto","Después del nacimiento","Lactancia"],"answer":0,"explanation":"Durante la organogénesis, hasta aproximadamente la semana 8, la exposición puede alterar la formación de órganos."},{"id":"c6-q4","classId":6,"difficulty":"easy","prompt":"¿Qué factor facilita el paso de un fármaco a la leche?","options":["Alta liposolubilidad","Unión completa a proteínas","Ausencia en plasma materno","Eliminación inmediata"],"answer":0,"explanation":"La alta liposolubilidad facilita el paso desde el plasma materno hacia la leche."},{"id":"c6-q5","classId":6,"difficulty":"easy","prompt":"¿Por qué el paciente pediátrico no es un adulto en miniatura?","options":["Porque ADME y respuesta maduran con la edad","Porque nunca absorbe fármacos","Porque no presenta RAM","Porque toda dosis es fija"],"answer":0,"explanation":"En pediatría cambian absorción, distribución, metabolismo, excreción y respuesta a medida que el organismo madura."},{"id":"c6-q6","classId":6,"difficulty":"medium","prompt":"¿Qué combinación favorece toxicidad por benzodiazepinas en un adulto mayor?","options":["Mayor sensibilidad y mayor entrada al SNC","Más aclaramiento renal y menor sensibilidad","Menor grasa y mayor albúmina","Mayor reserva fisiológica"],"answer":0,"explanation":"En el adulto mayor pueden aumentar la sensibilidad central y la penetración al SNC, favoreciendo sedación y caídas con benzodiazepinas."},{"id":"c6-q7","classId":6,"difficulty":"medium","prompt":"¿Qué describe una cascada de prescripción?","options":["Añadir un fármaco para tratar una RAM interpretada como enfermedad","Retirar medicamentos innecesarios","Iniciar con dosis baja","Usar una formulación líquida"],"answer":0,"explanation":"La cascada ocurre cuando una RAM se interpreta como una nueva enfermedad y se añade otro medicamento para tratarla."},{"id":"c6-q8","classId":6,"difficulty":"medium","prompt":"¿Por qué se evitan ibuprofeno, diclofenaco e indometacina en el tercer trimestre según la clase?","options":["Riesgo de cierre prematuro del ductus arterioso","Síndrome de niño gris","Aumento de producción de leche","Disminución de absorción materna"],"answer":0,"explanation":"Según la clase, los AINE indicados pueden favorecer cierre prematuro del ductus arterioso durante el tercer trimestre."},{"id":"c6-q9","classId":6,"difficulty":"medium","prompt":"Un neonato recibe un fármaco hidrosoluble. ¿Qué cambio modifica su distribución?","options":["Mayor agua corporal total","Mayor grasa y menor agua","Mayor unión a albúmina","Menor volumen extracelular"],"answer":0,"explanation":"El neonato tiene mayor proporción de agua corporal, lo que modifica el volumen de distribución de fármacos hidrosolubles."},{"id":"c6-q10","classId":6,"difficulty":"medium","prompt":"¿Qué significa START en la evaluación geriátrica?","options":["Detectar tratamientos beneficiosos que conviene iniciar","Suspender todos los fármacos","Clasificar riesgo fetal","Calcular dosis pediátrica"],"answer":0,"explanation":"START detecta omisiones: tratamientos potencialmente beneficiosos que convendría iniciar si están indicados."},{"id":"c6-q11","classId":6,"difficulty":"hard","prompt":"Una persona mayor presenta somnolencia y caídas tras iniciar una benzodiazepina. ¿Cuál es la explicación más coherente?","options":["Mayor sensibilidad farmacodinámica y penetración al SNC","Mayor aclaramiento y menor exposición","Ausencia de respuesta central","Aumento de receptores beta"],"answer":0,"explanation":"Somnolencia y caídas tras benzodiazepina se explican por mayor sensibilidad farmacodinámica y efecto central, no por eliminación acelerada."},{"id":"c6-q12","classId":6,"difficulty":"hard","prompt":"Una gestante requiere tratamiento durante la semana 6. ¿Qué riesgo domina en esa etapa?","options":["Malformaciones por exposición durante organogénesis","Solo toxicidad durante lactancia","Ningún riesgo porque la placenta bloquea fármacos","Exclusivamente cierre del ductus"],"answer":0,"explanation":"La semana 6 está dentro de la organogénesis, por lo que predominan las preocupaciones por malformaciones estructurales."},{"id":"c6-q13","classId":6,"difficulty":"hard","prompt":"Un recién nacido prematuro recibe un fármaco de eliminación renal. ¿Qué conducta se deduce?","options":["Ajustar y monitorizar por depuración inmadura","Usar dosis adulta sin controles","Duplicar la frecuencia","Asumir eliminación acelerada"],"answer":0,"explanation":"El prematuro tiene depuración renal inmadura; se deben individualizar dosis o intervalos y monitorizar respuesta y toxicidad."},{"id":"c6-q14","classId":6,"difficulty":"hard","prompt":"Una madre lactante necesita farmacoterapia. ¿Cuál estrategia minimiza exposición sin suspender automáticamente la lactancia?","options":["Elegir opción segura, dosis mínima, menor tiempo y planificar tomas","Usar varios fármacos simultáneos","Elegir el más liposoluble","Ignorar edad del lactante"],"answer":0,"explanation":"La exposición durante lactancia puede reducirse eligiendo una opción segura, la menor dosis y duración útiles y coordinando las tomas."},{"id":"c6-q15","classId":6,"difficulty":"hard","prompt":"Un niño recibe una indicación autorizada para adultos y se reduce la dosis solo por peso. ¿Cuál es la falla conceptual?","options":["No considerar maduración de ADME y guías por edad","Utilizar una vía oral","Evitar la polifarmacia","Vigilar concentraciones"],"answer":0,"explanation":"Reducir solo por peso ignora que la maduración de ADME y la respuesta cambian con la edad; deben usarse guías pediátricas apropiadas."}]},{"id":7,"title":"Bioequivalencia y farmacogenómica","short":"Bioequivalencia","focus":"AUC, Cmax, SCB, metabolizadores y técnicas genéticas","accent":"#3F638C","questions":[{"id":"c7-q1","classId":7,"difficulty":"easy","prompt":"¿Qué describe la biodisponibilidad?","options":["Cantidad y velocidad de acceso del fármaco a circulación","Solo el precio del medicamento","Únicamente su eliminación renal","La afinidad por un receptor"],"answer":0,"explanation":"La biodisponibilidad integra cuánto fármaco llega a la circulación y con qué rapidez lo hace."},{"id":"c7-q2","classId":7,"difficulty":"easy","prompt":"¿Qué parámetros se destacan para bioequivalencia in vivo?","options":["AUC y Cmax","pH y pKa solamente","Volumen de distribución y aclaramiento solamente","Emax y EC50"],"answer":0,"explanation":"AUC compara exposición total y Cmax compara concentración máxima; ambos son parámetros centrales en bioequivalencia in vivo."},{"id":"c7-q3","classId":7,"difficulty":"easy","prompt":"¿Cuál es el rango prueba/referencia enseñado para AUC y Cmax?","options":["80% a 125%","20% a 50%","50% a 75%","125% a 200%"],"answer":0,"explanation":"La clase enseña que el intervalo de aceptación para la razón prueba/referencia de AUC y Cmax es 80% a 125%."},{"id":"c7-q4","classId":7,"difficulty":"easy","prompt":"¿Qué clase SCB tiene alta solubilidad y alta permeabilidad?","options":["Clase I","Clase II","Clase III","Clase IV"],"answer":0,"explanation":"La clase I del Sistema de Clasificación Biofarmacéutica combina alta solubilidad con alta permeabilidad."},{"id":"c7-q5","classId":7,"difficulty":"easy","prompt":"¿Qué enzima activa principalmente clopidogrel según la clase?","options":["CYP2C19","CYP3A5 exclusivamente","Acetilcolinesterasa","Monoaminooxidasa"],"answer":0,"explanation":"Clopidogrel es un profármaco y la clase destaca a CYP2C19 como enzima relevante para producir su metabolito activo."},{"id":"c7-q6","classId":7,"difficulty":"medium","prompt":"¿Qué expresa principalmente el AUC?","options":["Exposición total al fármaco","Concentración mínima única","Afinidad por el receptor","Número de comprimidos"],"answer":0,"explanation":"El AUC es el área bajo la curva concentración-tiempo y representa la exposición total al fármaco."},{"id":"c7-q7","classId":7,"difficulty":"medium","prompt":"¿Por qué la clase III exige excipientes iguales o muy similares?","options":["Porque su baja permeabilidad puede alterarse con la formulación","Porque tiene baja solubilidad","Porque siempre posee margen estrecho","Porque se administra por vía intravenosa"],"answer":0,"explanation":"En clase III la permeabilidad es baja, por lo que diferencias en excipientes pueden modificar el tránsito o la absorción."},{"id":"c7-q8","classId":7,"difficulty":"medium","prompt":"¿Qué ocurre con un fármaco activo en un metabolizador pobre?","options":["Puede acumularse y aumentar toxicidad","Siempre pierde toda eficacia por falta de activación","Se elimina más rápido","No cambia su concentración"],"answer":0,"explanation":"Si el fármaco ya es activo, un metabolizador pobre puede eliminarlo más lentamente y aumentar concentración y toxicidad."},{"id":"c7-q9","classId":7,"difficulty":"medium","prompt":"¿Qué diferencia central presenta la farmacogenómica?","options":["Estudia influencias genómicas amplias y relaciones complejas","Solo compara precios","Mide únicamente biodisponibilidad","Excluye datos genéticos"],"answer":0,"explanation":"La farmacogenómica estudia influencias amplias del genoma y relaciones complejas, más allá de una sola variante o enzima."},{"id":"c7-q10","classId":7,"difficulty":"medium","prompt":"¿Qué limitación principal tiene un microarray?","options":["Detecta sobre todo variantes predefinidas","No puede analizar ADN","Solo sirve para AUC","Siempre identifica variantes nuevas"],"answer":0,"explanation":"Un microarray busca variantes que ya están definidas en su diseño; no es la mejor opción para descubrir variantes nuevas."},{"id":"c7-q11","classId":7,"difficulty":"hard","prompt":"Dos productos liberan el mismo principio activo por la misma vía, pero tienen distinta forma farmacéutica. ¿Cómo se clasifican inicialmente?","options":["Alternativas farmacéuticas","Equivalentes farmacéuticos demostrados","Bioequivalentes automáticamente","Productos idénticos"],"answer":0,"explanation":"Mismo principio activo y vía con distinta forma farmacéutica corresponde inicialmente a alternativas farmacéuticas."},{"id":"c7-q12","classId":7,"difficulty":"hard","prompt":"La relación AUC prueba/referencia es 75%. ¿Qué se concluye con el criterio enseñado?","options":["No cumple el rango de 80% a 125%","Cumple porque es mayor a 50%","Es bioequivalente sin revisar Cmax","La AUC no participa en la evaluación"],"answer":0,"explanation":"Una razón AUC de 75% cae por debajo del límite inferior de 80%, por lo que no cumple el criterio enseñado."},{"id":"c7-q13","classId":7,"difficulty":"hard","prompt":"Un principio activo SCB clase II se formula como liberación inmediata. ¿Qué limita la bioexención según la clase?","options":["Su baja solubilidad y la exclusión de clase II","Su alta solubilidad","Su alta permeabilidad por sí sola","La ausencia de principio activo"],"answer":0,"explanation":"La clase II tiene baja solubilidad y no entra en la bioexención descrita para formulaciones de liberación inmediata."},{"id":"c7-q14","classId":7,"difficulty":"hard","prompt":"Un paciente CYP2C19 *2/*2 presenta trombosis del stent pese a adherencia a clopidogrel. ¿Cuál es la cadena causal?","options":["Menos activación → menos metabolito activo → menos bloqueo P2Y12","Más activación → hemorragia → trombosis","Más eliminación renal → más bloqueo P2Y12","Mayor Cmax de ticagrelor"],"answer":0,"explanation":"CYP2C19 *2/*2 reduce la activación de clopidogrel, disminuye su metabolito activo y deja menos bloqueo de P2Y12."},{"id":"c7-q15","classId":7,"difficulty":"hard","prompt":"Se necesita buscar variantes conocidas y también nuevas en varios genes. ¿Qué técnica se ajusta mejor al objetivo?","options":["NGS","Microarray de variantes predefinidas solamente","AUC","Perfil de disolución"],"answer":0,"explanation":"NGS permite examinar múltiples genes y detectar tanto variantes conocidas como nuevas, según el objetivo planteado."}]},{"id":8,"title":"Antimicrobianos y seguridad clínica","short":"Antimicrobianos","focus":"Antibacterianos, antifúngicos, antiparasitarios, TDM y PROA","accent":"#C05442","questions":[{"id":"c8-q1","classId":8,"difficulty":"easy","prompt":"¿Qué blanco bloquean los β-lactámicos?","options":["PBP y síntesis de pared bacteriana","Ergosterol fúngico","Tubulina humana","Receptor nuclear"],"answer":0,"explanation":"Los beta-lactámicos se unen a PBP y bloquean la síntesis de pared, lo que compromete la integridad bacteriana."},{"id":"c8-q2","classId":8,"difficulty":"easy","prompt":"¿Qué toxicidades debes asociar rápidamente a aminoglucósidos?","options":["Nefrotoxicidad y ototoxicidad","Solo hepatotoxicidad","Tendinopatía","Síndrome serotoninérgico"],"answer":0,"explanation":"Los aminoglucósidos se asocian de manera característica con daño renal y auditivo, por lo que requieren vigilancia y a veces TDM."},{"id":"c8-q3","classId":8,"difficulty":"easy","prompt":"¿Cómo actúa anfotericina B?","options":["Se une a ergosterol y forma poros","Inhibe PBP","Bloquea folato","Quelata calcio"],"answer":0,"explanation":"Anfotericina B se une al ergosterol, forma poros y provoca fuga del contenido celular del hongo."},{"id":"c8-q4","classId":8,"difficulty":"easy","prompt":"¿Qué debe evitarse con metronidazol?","options":["Alcohol durante y 48 h después","Agua","Alimentos","Control neurológico"],"answer":0,"explanation":"El material indica evitar alcohol durante metronidazol y por 48 horas después, por el riesgo de efecto antabús."},{"id":"c8-q5","classId":8,"difficulty":"easy","prompt":"¿Qué diferencia colonización de infección?","options":["La infección implica invasión y clínica","La colonización siempre causa sepsis","Toda colonización se trata","Son sinónimos"],"answer":0,"explanation":"Colonización es presencia sin invasión ni clínica; infección implica invasión y respuesta clínica del paciente."},{"id":"c8-q6","classId":8,"difficulty":"medium","prompt":"¿Por qué una infusión prolongada puede favorecer a un β-lactámico?","options":["Mantiene más tiempo la concentración sobre la CMI","Aumenta obligatoriamente el Emax","Evita toda alergia","Lo vuelve concentración-dependiente"],"answer":0,"explanation":"Un beta-lactámico es tiempo-dependiente: una infusión prolongada puede aumentar el tiempo sobre la CMI."},{"id":"c8-q7","classId":8,"difficulty":"medium","prompt":"¿Qué significa obtener el valle de un aminoglucósido justo antes de la siguiente dosis?","options":["Evalúa acumulación y riesgo de toxicidad","Mide la biodisponibilidad oral","Confirma alergia","Mide la función hepática"],"answer":0,"explanation":"El valle se mide antes de la dosis siguiente y ayuda a detectar acumulación, asociada a mayor riesgo de toxicidad."},{"id":"c8-q8","classId":8,"difficulty":"medium","prompt":"¿Qué ocurre si ciprofloxacino se administra junto con calcio o hierro?","options":["Disminuye su absorción por quelación","Aumenta su absorción","Evita el QT largo","Se transforma en β-lactámico"],"answer":0,"explanation":"Calcio, hierro y otros cationes pueden quelar ciprofloxacino y disminuir su absorción oral."},{"id":"c8-q9","classId":8,"difficulty":"medium","prompt":"¿Qué cuadro sugiere vancomicina rápida con rubor y prurito?","options":["Síndrome del hombre rojo","Hemólisis por G6PD","Reacción de Mazzotti","C. difficile"],"answer":0,"explanation":"La infusión rápida de vancomicina puede liberar histamina y causar rubor y prurito, cuadro descrito como síndrome del hombre rojo."},{"id":"c8-q10","classId":8,"difficulty":"medium","prompt":"¿Cuándo es razonable evaluar el cambio IV a oral?","options":["Con mejoría, tolerancia oral y absorción adecuada","Siempre tras la primera dosis","Solo si empeora","Aunque vomite y esté inestable"],"answer":0,"explanation":"El cambio IV a oral se considera con mejoría, tolerancia oral y absorción adecuada, siempre que el foco no exija vía IV."},{"id":"c8-q11","classId":8,"difficulty":"hard","prompt":"Se extrae un nivel de vancomicina demasiado pronto y parece muy alto. ¿Cuál es el riesgo?","options":["Interpretarlo falsamente alto y reducir una dosis necesaria","Confundirlo con un nivel falsamente bajo","Eliminar el primer paso","Aumentar la absorción oral"],"answer":0,"explanation":"Una extracción demasiado precoz puede parecer falsamente alta y llevar a reducir una dosis que el paciente todavía necesita."},{"id":"c8-q12","classId":8,"difficulty":"hard","prompt":"Paciente con linezolid y sertralina desarrolla agitación, temblor, fiebre y taquicardia. ¿Qué sospechas?","options":["Síndrome serotoninérgico","Hombre rojo","Reacción de Mazzotti","Déficit de G6PD"],"answer":0,"explanation":"Linezolid junto a un ISRS como sertralina puede aumentar señal serotoninérgica y producir agitación, temblor, fiebre y taquicardia."},{"id":"c8-q13","classId":8,"difficulty":"hard","prompt":"Se propone mezclar gentamicina con piperacilina-tazobactam en la misma solución IV. ¿Qué problema señala el material?","options":["Inactivación química; deben separarse","Mayor biodisponibilidad","Activación del profármaco","Prevención de nefrotoxicidad"],"answer":0,"explanation":"Un beta-lactámico y un aminoglucósido pueden inactivarse químicamente en la misma solución; deben separarse o confirmarse compatibilidad."},{"id":"c8-q14","classId":8,"difficulty":"hard","prompt":"Paciente con sepsis e hipotensión requiere cultivos. ¿Qué conducta integra el material?","options":["Tomarlos sin retrasar el antibiótico urgente dentro del tiempo indicado","Esperar siempre el resultado antes de tratar","Administrar vía oral y reevaluar en días","Tratar solo si el cultivo es positivo"],"answer":0,"explanation":"Los cultivos se toman si no retrasan la terapia. La hipotensión y la sospecha de sepsis exigen antibiótico urgente según el material."},{"id":"c8-q15","classId":8,"difficulty":"hard","prompt":"Paciente crítico con edema y falla renal recibe un antimicrobiano estrecho. ¿Cuál es la mejor lógica?","options":["Vd y eliminación pueden cambiar; individualizar con función renal y TDM","Usar siempre dosis estándar","El edema evita toda toxicidad","La falla renal aumenta aclaramiento"],"answer":0,"explanation":"El edema puede cambiar el volumen de distribución y la falla renal la eliminación; por eso se individualiza usando función renal y TDM."}]},{"id":9,"title":"Farmacocinética y farmacodinamia","short":"PK/PD","focus":"ADME, biodisponibilidad, curvas dosis-respuesta y antagonismo","accent":"#2C728A","questions":[{"id":"c9-q1","classId":9,"difficulty":"easy","prompt":"¿Qué procesos reúne ADME?","options":["Absorción, distribución, metabolismo y excreción","Afinidad, dosis, mecanismo y eficacia","Agonismo, distribución, metabolismo y enzimas","Absorción, dilución, membrana y efecto"],"answer":0,"explanation":"ADME resume absorción, distribución, metabolismo y excreción: el recorrido del fármaco por el organismo."},{"id":"c9-q2","classId":9,"difficulty":"easy","prompt":"¿Qué describe la farmacodinámica?","options":["Los efectos y mecanismos del fármaco en el organismo","Solo la eliminación renal","Solo la concentración plasmática","La fabricación del medicamento"],"answer":0,"explanation":"La farmacodinámica estudia qué hace el fármaco al organismo, incluidos sus blancos, mecanismos y efectos."},{"id":"c9-q3","classId":9,"difficulty":"easy","prompt":"¿Qué representa el AUC?","options":["La exposición total al fármaco","El tiempo exacto al pico","La respuesta máxima del receptor","La cantidad unida a albúmina"],"answer":0,"explanation":"El área bajo la curva concentración-tiempo representa la exposición total al fármaco."},{"id":"c9-q4","classId":9,"difficulty":"easy","prompt":"¿Qué significa una EC50 menor?","options":["Mayor potencia","Menor eficacia obligatoria","Mayor volumen de distribución","Menor afinidad obligatoria"],"answer":0,"explanation":"Una EC50 menor significa que se necesita menor concentración para lograr 50% del efecto máximo: mayor potencia."},{"id":"c9-q5","classId":9,"difficulty":"easy","prompt":"¿Qué variable compara la eficacia?","options":["Emax","Tmax","AUC","t1/2"],"answer":0,"explanation":"Emax es la meseta de la curva dosis-respuesta y permite comparar eficacia máxima."},{"id":"c9-q6","classId":9,"difficulty":"medium","prompt":"¿Por qué la vía oral puede tener menor biodisponibilidad que la IV?","options":["Puede existir absorción incompleta y primer paso","Siempre entra directo a sangre","Evita intestino e hígado","No atraviesa ninguna membrana"],"answer":0,"explanation":"Por vía oral puede haber absorción incompleta y metabolismo de primer paso antes de alcanzar la circulación sistémica."},{"id":"c9-q7","classId":9,"difficulty":"medium","prompt":"Un fármaco presenta Vd alto. ¿Qué interpretación corresponde?","options":["Se distribuye ampliamente y queda poca concentración en plasma","Permanece exclusivamente en plasma","No puede atravesar membranas","Su Emax necesariamente es mayor"],"answer":0,"explanation":"Un Vd alto sugiere distribución amplia fuera del plasma; no informa por sí solo sobre Emax."},{"id":"c9-q8","classId":9,"difficulty":"medium","prompt":"¿Qué diferencia al transporte activo de la difusión facilitada?","options":["Puede ir contra gradiente y requiere energía","Nunca usa proteínas","Solo ocurre entre células","Siempre reduce la absorción"],"answer":0,"explanation":"El transporte activo usa una proteína y energía y puede ir contra gradiente; la difusión facilitada no consume energía neta."},{"id":"c9-q9","classId":9,"difficulty":"medium","prompt":"¿Qué cambio produce un antagonista competitivo?","options":["Aumenta EC50 y conserva Emax","Reduce Emax sin desplazamiento","Aumenta Emax","Transforma al agonista en profármaco"],"answer":0,"explanation":"El antagonista competitivo desplaza la curva a la derecha: aumenta EC50, pero suficiente agonista aún puede alcanzar el mismo Emax."},{"id":"c9-q10","classId":9,"difficulty":"medium","prompt":"En el ejercicio de curvas, A está más a la izquierda y C alcanza mayor meseta. ¿Cuál es la lectura?","options":["A es más potente y C más eficaz","C es más potente y A más eficaz","A y C tienen igual potencia","La posición no informa potencia"],"answer":0,"explanation":"La curva más a la izquierda indica mayor potencia; la meseta más alta indica mayor eficacia."},{"id":"c9-q11","classId":9,"difficulty":"hard","prompt":"Lovastatina se administra con un inhibidor de CYP3A4 y su curva plasmática aumenta. ¿Qué secuencia lo explica?","options":["Menor metabolismo → mayor concentración y AUC","Mayor metabolismo → menor AUC","Menor absorción → mayor Cmax","Mayor excreción → mayor exposición"],"answer":0,"explanation":"Inhibir CYP3A4 reduce el metabolismo de lovastatina, eleva concentración y aumenta el AUC."},{"id":"c9-q12","classId":9,"difficulty":"hard","prompt":"Indinavir se administra con un inductor enzimático y disminuye su concentración. ¿Cuál es la deducción?","options":["Aumenta su metabolismo y puede perder efecto","Disminuye su metabolismo y aumenta toxicidad","Aumenta su Emax receptor","Disminuye su volumen corporal"],"answer":0,"explanation":"Un inductor aumenta la capacidad metabólica, reduce la exposición de indinavir y puede provocar fracaso terapéutico."},{"id":"c9-q13","classId":9,"difficulty":"hard","prompt":"Fármaco A tiene EC50 menor pero Emax 60; fármaco B tiene EC50 mayor y Emax 100. ¿Cuál afirmación es correcta?","options":["A es más potente y B más eficaz","B es más potente y A más eficaz","A es más potente y más eficaz","EC50 y Emax significan lo mismo"],"answer":0,"explanation":"A tiene menor EC50 y por eso es más potente; B alcanza mayor Emax y por eso es más eficaz."},{"id":"c9-q14","classId":9,"difficulty":"hard","prompt":"Tras un antagonista, la curva del agonista alcanza una meseta menor aunque aumente su concentración. ¿Qué tipo sugiere?","options":["Antagonismo no competitivo","Antagonismo competitivo superable","Agonismo completo","Difusión facilitada"],"answer":0,"explanation":"Si aumentar agonista no recupera la meseta, el patrón sugiere antagonismo no competitivo con reducción de Emax."},{"id":"c9-q15","classId":9,"difficulty":"hard","prompt":"Con dosis repetidas de morfina, la curva se desplaza a la derecha. ¿Qué mecanismo integra la clase?","options":["Tolerancia por desensibilización, internalización o downregulation","Mayor eficacia por aumento de Emax","Bioequivalencia por aumento de AUC","Absorción IV incompleta"],"answer":0,"explanation":"El desplazamiento a la derecha con dosis repetidas indica tolerancia, explicada por desensibilización, internalización o downregulation."}]}]};
